#!/usr/bin/env node

/**
 * Compare benchmark results between main and PR branches
 * Outputs a compact markdown report with mean-time changes.
 *
 * Expects JSON files generated by vitest's benchmark.outputJson config option.
 * Format: { files: [{ filepath, groups: [{ fullName, benchmarks: [{ name, hz, mean, ... }] }] }] }
 */

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const mainResultsFile = 'main-results.json'
const prResultsFile = 'pr-results.json'
const outputFile = 'benchmark-comparison.md'

// A benchmark name is only unique within its suite. Include the file as well so
// equally named suites in different benchmark files remain distinct.
function benchmarkId(filePath, suiteName, benchmarkName) {
  return JSON.stringify([filePath, suiteName, benchmarkName])
}

function escapeMarkdown(value) {
  return String(value).replaceAll('|', '\\|')
}

// Parse vitest benchmark.outputJson format
export function parseBenchmarkResults(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`File not found: ${filePath}`)
    return null
  }

  const content = fs.readFileSync(filePath, 'utf8')
  const benchmarks = new Map()

  try {
    const data = JSON.parse(content)

    if (!data.files) {
      console.error(`Invalid benchmark format in ${filePath}`)
      return null
    }

    for (const file of data.files) {
      for (const group of file.groups || []) {
        for (const bench of group.benchmarks || []) {
          const benchmarkFile = file.filepath || '(unknown file)'
          const suiteName = group.fullName || group.name || '(unnamed suite)'

          // Vitest includes entries for benchmarks that never collected a
          // sample (for example, an optional native library that cannot run
          // on the current Node version). Those entries have no usable mean
          // and cannot be compared meaningfully.
          if (!Number.isFinite(bench.mean) || bench.mean <= 0) {
            console.warn(
              `Skipping incomplete benchmark result: ${suiteName} > ${bench.name}`,
            )
            continue
          }

          const id = benchmarkId(benchmarkFile, suiteName, bench.name)

          benchmarks.set(id, {
            id,
            name: bench.name,
            mean: bench.mean,
          })
        }
      }
    }
  } catch (e) {
    console.error(`Failed to parse ${filePath}: ${e.message}`)
    return null
  }

  return benchmarks
}

// Calculate percentage change
function percentChange(oldVal, newVal) {
  if (oldVal === 0) return newVal === 0 ? 0 : 100
  return ((newVal - oldVal) / oldVal) * 100
}

// Format percentage with color indicators
function formatChange(change) {
  const absChange = Math.abs(change)
  const sign = change >= 0 ? '+' : ''
  const formatted = `${sign}${change.toFixed(2)}%`

  if (absChange < 1) {
    return formatted // No significant change
  } else if (change < 0) {
    return `🟢 ${formatted}` // Improvement
  } else {
    return `🔴 ${formatted}` // Regression
  }
}

// Main comparison logic
export function compareResults({
  mainFile = mainResultsFile,
  prFile = prResultsFile,
  reportFile = outputFile,
} = {}) {
  console.log('Comparing benchmark results...')

  const mainResults = parseBenchmarkResults(mainFile)
  const prResults = parseBenchmarkResults(prFile)

  if (!mainResults || !prResults) {
    console.error('Failed to parse benchmark results')
    return false
  }

  if (mainResults.size === 0 || prResults.size === 0) {
    console.error('No benchmark data found')
    return false
  }

  console.log(`Found ${mainResults.size} benchmarks in main`)
  console.log(`Found ${prResults.size} benchmarks in PR`)

  let markdown = `Comparing **${prResults.size}** benchmarks between \`main\` and this PR.\n\n`
  markdown +=
    '<details>\n<summary><strong>Performance changes</strong></summary>\n\n'
  markdown += '| Benchmark | Main (ms) | PR (ms) | Change |\n'
  markdown += '|-----------|-----------|---------|--------|\n'

  const changes = []

  // Compare common benchmarks
  for (const prData of prResults.values()) {
    const mainData = mainResults.get(prData.id)
    const benchmarkName = escapeMarkdown(prData.name)

    if (!mainData) {
      // New benchmark in PR
      markdown += `| ${benchmarkName} | - | ${prData.mean.toFixed(2)} | 🆕 New |\n`
      continue
    }

    const meanChange = percentChange(mainData.mean, prData.mean)

    changes.push({ meanChange })

    markdown += `| ${benchmarkName} | ${mainData.mean.toFixed(2)} | ${prData.mean.toFixed(2)} | ${formatChange(meanChange)} |\n`
  }

  // Check for removed benchmarks
  for (const mainData of mainResults.values()) {
    if (!prResults.has(mainData.id)) {
      markdown += `| ${escapeMarkdown(mainData.name)} | ${mainData.mean.toFixed(2)} | - | ❌ Removed |\n`
    }
  }

  markdown += '\n</details>\n'

  // Summary statistics
  if (changes.length > 0) {
    const avgMeanChange =
      changes.reduce((sum, c) => sum + c.meanChange, 0) / changes.length
    const improvements = changes.filter((c) => c.meanChange < -1).length
    const regressions = changes.filter((c) => c.meanChange > 1).length
    const neutral = changes.length - improvements - regressions

    markdown += '\n'
    markdown += `- **Average scenario time change**: ${formatChange(avgMeanChange)}\n`
    markdown += `- **Faster** (>1%): ${improvements}\n`
    markdown += `- **Slower** (>1%): ${regressions}\n`
    markdown += `- **Unchanged** (±1%): ${neutral}\n`

    if (regressions > 0) {
      markdown +=
        '\n⚠️ **Warning**: Some benchmarks show performance regressions.\n'
    } else if (improvements > regressions) {
      markdown += '\n✅ Overall performance looks good!\n'
    }
  }

  // Write output
  fs.writeFileSync(reportFile, markdown)
  console.log(`Comparison written to ${reportFile}`)

  return true
}

// Run comparison when invoked directly, but keep the parser and comparison
// callable from tests.
const invokedFile = process.argv[1] && path.resolve(process.argv[1])
const currentFile = fileURLToPath(import.meta.url)

if (invokedFile === currentFile) {
  const success = compareResults()
  process.exit(success ? 0 : 1)
}
